{id:"groundnuts_india_export_policy", label:"India tightens groundnut export policy", cat:"Groundnut sector", baseSev:0.32, sevUnit:'×', channel:0,
    desc:"India is one of the world's largest groundnut exporters, supplying shelled kernels and groundnut oil to Indonesia, Vietnam, Malaysia and the EU; a weak monsoon plus domestic edible-oil price politics prompts export curbs or minimum-export-price rules that choke Indian kernel shipments (USDA FAS, Indian Oilseeds & Produce Export Promotion Council).",
    formula:"Δ = (shocked-exporter share of this country's groundnuts imports) × severity × 38; non-shocked exporters get minor relief.",
    _shockIso:"IND", _src:"USDA FAS / IOPEPC India", _commodity:"groundnuts",
    kick: function(c, sv=0.32) {
      try {
        if (!c || !c.iso) return 0;
        const shockIso="IND";
        if (c.iso===shockIso) return 0;
        const imp=(typeof curatedPartners==='function')?curatedPartners(c,"Groundnuts",'import'):null;
        if (imp && imp.length) {
          const tot=imp.reduce((a,p)=>a+(p.kt||0),0)||1;
          const fromShock=imp.filter(p=>p.iso===shockIso).reduce((a,p)=>a+(p.kt||0),0);
          return Math.pow(fromShock/tot,0.85)*sv*38;
        }
        const exp=(typeof curatedPartners==='function')?curatedPartners(c,"Groundnuts",'export'):null;
        if (exp && exp.length) return -Math.min(5, sv*8);
        return 0;
      } catch(e){ return 0; }
    },
    impact: function(c, sv=0.32){ return Math.round(this.kick(c, sv)); }}

